// generated by scripts/mktests.py
use neutral_parity::{check, load, Case, Outcome};
use std::path::PathBuf;

pub fn run(name: &str, f: impl Fn(&Case) -> Outcome) {
    let dir = match std::env::var("PORTA_VECTORS") {
        Ok(d) => PathBuf::from(d),
        Err(_) => PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("..").join("vectors"),
    };
    let path = dir.join(format!("{}.vec", name));
    let vf = load(&path).unwrap();
    let rep = check(&vf, f);
    println!("PARITY {} compared={} skipped={} failed={}", name, rep.compared, rep.skipped, rep.failed);
    rep.assert_ok(450);
}

/// Absolute address the oracle gave pointer argument `i` (tools/oracle.py: buffers start at
/// 0x20000000 + 0x400000 * i, placed so the last byte ends a page; pointer = start + off).
pub fn ptr(c: &Case, i: usize) -> u64 {
    let size = c.buf(i).len() as u64;
    let rsz = (size + 0xfff) & !0xfff;
    0x2000_0000 + (i as u64) * 0x40_0000 + rsz - size + c.buf_off(i) as u64
}

/// The dump itself, as the oracle maps it: read-only at 0x10000000, zero padded to a page.
pub const CODE_BASE: u64 = 0x1000_0000;

fn code_image() -> &'static Vec<u8> {
    static CODE: std::sync::OnceLock<Vec<u8>> = std::sync::OnceLock::new();
    CODE.get_or_init(|| {
        let mut dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
        for _ in 0..8 {
            let p = dir.join("original").join("neutral_3.text.bin");
            if p.exists() {
                let mut v = std::fs::read(&p).unwrap();
                let padded = (v.len() + 0xfff) & !0xfff;
                v.resize(padded, 0);
                return v;
            }
            if !dir.pop() {
                break;
            }
        }
        panic!("original/neutral_3.text.bin not found above the crate directory");
    })
}

/// The buffers of one case as flat memory at the addresses the oracle used, plus the code image
/// (read only; a write to it faults in the oracle, so such cases never reach the port).
pub struct OracleMem {
    regions: Vec<(usize, u64, Vec<u8>)>,
    code: &'static [u8],
}

impl OracleMem {
    pub fn new(c: &Case) -> Self {
        let mut regions = Vec::new();
        for i in 0..c.args.len() {
            if let neutral_parity::Arg::Buf { data, off, .. } = &c.args[i] {
                regions.push((i, ptr(c, i) - *off as u64, data.clone()));
            }
        }
        OracleMem { regions, code: code_image().as_slice() }
    }
    pub fn take(&self, i: usize) -> Vec<u8> {
        self.regions.iter().find(|r| r.0 == i).unwrap().2.clone()
    }
    fn in_code(&self, a: u64) -> bool {
        a >= CODE_BASE && a < CODE_BASE + self.code.len() as u64
    }
    fn find(&self, a: u64) -> usize {
        self.regions
            .iter()
            .position(|r| a >= r.1 && a < r.1 + r.2.len() as u64)
            .unwrap_or_else(|| panic!("access outside the oracle buffers at {:#x}", a))
    }
}

impl lift_a::Mem for OracleMem {
    fn rd8(&self, a: u64) -> u8 {
        if self.in_code(a) {
            return self.code[(a - CODE_BASE) as usize];
        }
        let k = self.find(a);
        self.regions[k].2[(a - self.regions[k].1) as usize]
    }
    fn wr8(&mut self, a: u64, v: u8) {
        if self.in_code(a) {
            panic!("write to the code image at {:#x}", a);
        }
        let k = self.find(a);
        let base = self.regions[k].1;
        self.regions[k].2[(a - base) as usize] = v;
    }
}
